document.querySelectorAll('[data-contracts]').forEach(function(s){var d=false,sx=0,sl=0,dd=0;s.addEventListener('mousedown',function(e){d=true;s.style.cursor='grabbing';sx=e.pageX;sl=s.scrollLeft;dd=0;});['mouseup','mouseleave'].forEach(function(ev){s.addEventListener(ev,function(){d=false;s.style.cursor='';});});s.addEventListener('mousemove',function(e){if(!d)return;e.preventDefault();var dx=e.pageX-sx;dd=Math.abs(dx);s.scrollLeft=sl-dx;});s.addEventListener('click',function(e){if(dd>6){e.preventDefault();e.stopPropagation();}dd=0;},true);});